// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
dimensions [0 1 0 0 0 0 0];
internalField uniform (0 0 0);
boundaryField
{
free
{
patchType overset;
type cellMotion;
value uniform (0 0 0);
}
"(walls|hole|left1|right1)"
{
type cellMotion;
value uniform (0 0 0);
}
frontAndBack
{
