dimensions [0 1 0 0 0 0 0];
internalField uniform (0 0 0);
boundaryField
{
".*"
{
type uniformFixedValue;
uniformValue (0 0 0);
}
"(free|hole)"
{
patchType overset;
type uniformFixedValue;
uniformValue table
(
(0.0 (0 0 0))
(1.0 (0.2 0 0))
(2.0 (0 0 0))
);
}
}
