#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
cp -rf \
"$FOAM_TUTORIALS"/resources/geometry/annularCombustorTurbine \
constant/triSurface
runApplication blockMesh
runApplication -s cyclic \
createPatch -dict system/createPatchDict.cyclic -overwrite
runApplication snappyHexMesh -overwrite
rm -rf 0
runApplication -s ami \
createPatch -dict system/createPatchDict.ami -overwrite
runApplication transformPoints -scale 0.01 # Uniform scaling [cm] -> [m]
runApplication mergeOrSplitBaffles -split -overwrite
#------------------------------------------------------------------------------
cd 切换当前工作目录。
cp 复制文件或目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
createPatch 把已有边界面或 faceSet 重组为指定 patch。结果覆盖当前网格。
snappyHexMesh 细化背景网格，贴合几何表面，并按设置生成边界层。结果覆盖当前网格。
rm 删除指定的文件或目录。
transformPoints 平移、旋转或缩放网格坐标，可同步旋转向量与张量场。
mergeOrSplitBaffles 检测共用顶点的挡板面，并合并或拆分它们。结果覆盖当前网格。
